@Service
public class PaymentCallbackService {

    @Autowired
    private OrderMapper orderMapper;
    @Autowired
    private CallbackLogMapper callbackLogMapper;

    /**
     * 处理支付网关回调
     * @param payOrderId 业务支付单号（幂等键）
     * @param gatewayTradeNo 网关交易号
     * @param notifyId 网关通知ID（用于去重）
     */
    @Transactional
    public CallbackResult handleCallback(String payOrderId, String gatewayTradeNo, String notifyId) {
        // 第一步：去重表 check-and-insert，利用主键唯一性防并发
        CallbackLog log = new CallbackLog();
        log.setPayOrderId(payOrderId);
        log.setNotifyId(notifyId);
        log.setGatewayTradeNo(gatewayTradeNo);
        log.setProcessedAt(LocalDateTime.now());
        try {
            callbackLogMapper.insert(log); // 主键 (payOrderId, notifyId)
        } catch (DuplicateKeyException e) {
            // 已处理过，直接返回成功（支付网关要求返回成功码）
            return CallbackResult.success("duplicate callback, already processed");
        }

        // 第二步：状态机更新，只有 PAYING 状态才能转为 PAID
        int affected = orderMapper.updateStatus(
                payOrderId,
                OrderStatus.PAYING,   // 期望的当前状态
                OrderStatus.PAID      // 目标状态
        );
        // 对应 SQL: UPDATE orders SET status = 'PAID', gateway_trade_no = ?
        //           WHERE pay_order_id = ? AND status = 'PAYING'

        if (affected == 0) {
            // 状态已经是 PAID 或其他终态，幂等返回成功
            return CallbackResult.success("order already in terminal state");
        }

        // 第三步：执行后续业务（发消息、更新积分等）
        orderService.onPaymentSuccess(payOrderId, gatewayTradeNo);

        return CallbackResult.success("payment confirmed");
    }
}
